(function(){
const C=window.BloomContent;let draft=C.merge({}),published=C.merge({});
const tab=document.createElement('button');tab.dataset.tab='content';tab.textContent='Website content';tab.setAttribute('aria-pressed','false');document.querySelector('.tabs').append(tab);
const section=document.createElement('section');section.id='content';section.hidden=true;section.innerHTML='<h2>Make the website yours.</h2><p>Save a draft, preview it, then publish. Website text, photos and settings use this workflow. Treatment edits in the Treatments tab go live immediately.</p><div class="toolbar"><button type="button" id="save-content">Save draft</button><button type="button" id="preview-content" class="secondary">Preview draft ↗</button><button type="button" id="publish-content">Publish changes</button><button type="button" id="restore-content" class="secondary">Restore published content</button></div><p id="content-status" role="status"></p><form id="content-form"></form>';
document.querySelector('#dashboard').append(section);
const css=document.createElement('style');css.textContent='#content details{border:1px solid #e4d4dc;border-radius:12px;padding:20px;margin:16px 0;background:white}#content summary{cursor:pointer;font-weight:bold;font-size:18px}.content-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:22px}.content-field textarea{min-height:100px}.content-field img,.service-form img{max-width:180px;height:100px;object-fit:cover;border-radius:8px;display:block;margin:10px 0}.gallery-edit{padding:18px;background:#f5e8e5;border-radius:10px;margin-top:15px}.content-field input[type=checkbox]{width:auto}.content-field input[type=color]{height:45px}.hours-edit{display:grid;grid-template-columns:110px 1fr 1fr 80px;gap:10px;align-items:center}.hours-edit input[type=checkbox]{width:auto}@media(max-width:650px){.content-fields{grid-template-columns:1fr}.hours-edit{grid-template-columns:1fr 1fr}.hours-edit b{grid-column:1/-1}}';document.head.append(css);
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));['appointments','treatments','content'].forEach(id=>document.querySelector('#'+id).hidden=b.dataset.tab!==id)});
function fieldHTML([key,label,group,type]){const value=draft[key];if(type==='checkbox')return `<label class="content-field"><input data-content="${key}" type="checkbox" ${value?'checked':''}> ${esc(label)}</label>`;return `<label class="content-field">${esc(label)}${type==='textarea'?`<textarea data-content="${key}" maxlength="12000">${esc(value)}</textarea>`:`<input data-content="${key}" type="${type==='image'?'text':type}" value="${esc(value)}" ${type==='number'?'min="0.01" step="any"':''}>`}${type==='image'?`<input type="file" data-upload="${key}" accept="image/jpeg,image/png,image/webp,image/avif"><small>JPEG, PNG, WebP or AVIF · up to 5 MB. Uploading does not publish.</small>${value&&C.safeImage(value)?`<img src="${esc(value)}" alt="Current ${esc(label)}">`:''}`:''}</label>`}
function render(){const groups={policies:'Privacy & booking policies',brand:'Brand & colours',navigation:'Navigation & buttons',hero:'Homepage hero & ribbon',treatments:'Treatment section text',studio:'Studio story',gallery:'Gallery headings',contact:'Contact & social links',booking:'Booking settings',currency:'Currency settings',footer:'Footer',visibility:'Sections & animations'};document.querySelector('#content-form').innerHTML=Object.entries(groups).map(([key,title])=>`<details><summary>${title}</summary><div class="content-fields">${C.fields.filter(f=>f[2]===key).map(fieldHTML).join('')}</div></details>`).join('')+'<details><summary>Gallery photos</summary><p>Add photos, captions and descriptions. Reorder them with the arrows.</p><div id="gallery-editor"></div><button type="button" id="add-gallery" class="secondary">Add gallery photo</button></details><details><summary>Opening hours</summary><p>Hours apply to booking validation as well as the website.</p>'+draft.hours.map((h,i)=>`<div class="hours-edit"><b>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][h.day]}</b><label>Open<input data-hour="${i}" data-part="open" type="time" value="${esc(h.open)}"></label><label>Close<input data-hour="${i}" data-part="close" type="time" value="${esc(h.close)}"></label><label>Closed<input data-hour="${i}" data-part="closed" type="checkbox" ${h.closed?'checked':''}></label></div>`).join('')+'</details>';renderGallery();addPhotoPickers()}
function addPhotoPickers(){if(!window.bloomFocus)return;for(const [key,shape] of [['hero_image','circle'],['studio_image','arch'],['visit_image','wide']]){const input=document.querySelector(`[data-content="${key}"]`);if(!input)continue;const posKey=key.replace('_image','_pos'),hidden=document.createElement('input');hidden.type='hidden';hidden.dataset.content=posKey;hidden.value=window.bloomFocus.valid(draft[posKey])?draft[posKey]:'50% 50%';const pick=window.bloomFocus.picker({src:C.safeImage(input.value)?input.value:'',value:hidden.value,shape,onChange:v=>hidden.value=v});const host=input.closest('label')||input;host.after(hidden,pick);const sync=()=>pick.setSrc(C.safeImage(input.value)?input.value:'');input.addEventListener('input',sync);input.addEventListener('change',sync);new MutationObserver(sync).observe(input,{attributes:true,attributeFilter:['value']})}}
function renderGallery(){document.querySelector('#gallery-editor').innerHTML=draft.gallery.map((g,i)=>`<div class="gallery-edit"><div class="content-fields"><label>Image URL<input data-gallery="${i}" data-part="image" value="${esc(g.image)}"><input type="file" data-gallery-upload="${i}" accept="image/jpeg,image/png,image/webp,image/avif">${C.safeImage(g.image)?`<img style="max-width:150px;max-height:110px" src="${esc(g.image)}" alt="Gallery preview">`:''}</label><div><label>Caption<input data-gallery="${i}" data-part="caption" value="${esc(g.caption)}"></label><label>Photo description<input data-gallery="${i}" data-part="alt" value="${esc(g.alt)}"></label></div></div><button type="button" data-gallery-move="${i}" data-step="-1" class="secondary">↑</button> <button type="button" data-gallery-move="${i}" data-step="1" class="secondary">↓</button> <button type="button" data-gallery-remove="${i}" class="secondary">Remove from gallery</button></div>`).join('');if(window.bloomFocus)document.querySelectorAll('#gallery-editor .gallery-edit').forEach((box,i)=>{const g=draft.gallery[i],hidden=document.createElement('input');hidden.type='hidden';hidden.dataset.gallery=i;hidden.dataset.part='pos';hidden.value=window.bloomFocus.valid(g.pos)?g.pos:'50% 50%';box.querySelector('.content-fields').after(hidden,window.bloomFocus.picker({src:C.safeImage(g.image)?g.image:'',value:hidden.value,shape:g.video?'reel':'arch',onChange:v=>hidden.value=v}))})}
function collect(){document.querySelectorAll('[data-content]').forEach(el=>draft[el.dataset.content]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value);document.querySelectorAll('[data-gallery]').forEach(el=>draft.gallery[Number(el.dataset.gallery)][el.dataset.part]=el.value);document.querySelectorAll('[data-hour]').forEach(el=>draft.hours[Number(el.dataset.hour)][el.dataset.part]=el.type==='checkbox'?el.checked:el.value);return draft}
function validate(){collect();if(!/^\+\d{8,15}$/.test(draft.whatsapp.replace(/[ .()-]/g,'')))throw Error('Enter a WhatsApp number with + and country code.');if(!Number.isFinite(draft.zmw_per_usd)||draft.zmw_per_usd<=0)throw Error('Exchange rate must be greater than zero.');if(!['USD','ZMW'].includes(draft.default_currency))throw Error('Default currency must be ZMW or USD.');if(!Number.isInteger(draft.slot_minutes)||draft.slot_minutes<5||draft.slot_minutes>120)throw Error('Time slot spacing must be a whole number from 5 to 120 minutes.');for(const h of draft.hours){if(!h.closed&&(!/^\d{2}:\d{2}$/.test(h.open)||!/^\d{2}:\d{2}$/.test(h.close)||h.open>=h.close))throw Error('Each open day needs an opening time before its closing time.')}for(const f of C.fields.filter(f=>f[3]==='image'))if(draft[f[0]]&&!C.safeImage(draft[f[0]]))throw Error('Photo links must use HTTPS or a saved website asset.');for(const g of draft.gallery)if(!C.safeImage(g.image))throw Error('Each gallery photo needs a valid uploaded image or HTTPS URL.');return draft}
async function upload(file){if(!['image/jpeg','image/png','image/webp','image/avif'].includes(file.type)||file.size>5242880)throw Error('Choose a JPEG, PNG, WebP or AVIF photo up to 5 MB.');const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/avif':'avif'}[file.type],path='photos/'+crypto.randomUUID()+'.'+ext;const r=await fetch(API+'/storage/v1/object/bloom-website/'+path,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+await token(),'Content-Type':file.type},body:file,signal:AbortSignal.timeout(60000)});if(!r.ok)throw Error('Photo upload failed. Check your admin login and file size.');return API+'/storage/v1/object/public/bloom-website/'+path}
const okVideo=u=>/^(https:\/\/|assets\/)[^\s"'<>]{1,590}$/.test(u||'');
function playable(file){return new Promise(res=>{const v=document.createElement('video'),u=URL.createObjectURL(file),done=ok=>{clearTimeout(t);URL.revokeObjectURL(u);res(ok)},t=setTimeout(()=>done(true),10000);v.muted=true;v.preload='metadata';v.onloadedmetadata=()=>done(v.videoWidth>0||v.duration>0);v.onerror=()=>done(false);v.src=u})}
async function uploadVideo(file){const types={'video/mp4':'mp4','video/quicktime':'mov','video/webm':'webm'};if(!types[file.type])throw Error('Choose an MP4, MOV or WebM video.');if(file.size>52428800)throw Error('Videos can be up to 50 MB. Trim it or send it to yourself on WhatsApp first to make it smaller.');if(!await playable(file))throw Error('This video format will not play in web browsers. On iPhone go to Settings › Camera › Formats and choose “Most Compatible”, or send the video to yourself on WhatsApp, save it, and upload that copy.');const path='videos/'+crypto.randomUUID()+'.'+types[file.type];const r=await fetch(API+'/storage/v1/object/bloom-website/'+path,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+await token(),'Content-Type':file.type},body:file,signal:AbortSignal.timeout(300000)});if(!r.ok)throw Error('Video upload failed. Check your connection and try again.');return API+'/storage/v1/object/public/bloom-website/'+path}
document.querySelector('#content-form').oninput=collect;document.querySelector('#content-form').onsubmit=e=>e.preventDefault();
document.querySelector('#content-form').onchange=async e=>{const el=e.target;if(el.dataset.upload===undefined&&el.dataset.galleryUpload===undefined)return;const file=el.files[0];if(!file)return;el.disabled=true;document.querySelector('#content-status').textContent='Uploading photo…';try{collect();const url=await upload(file);if(el.dataset.upload!==undefined){draft[el.dataset.upload]=url;document.querySelector(`[data-content="${el.dataset.upload}"]`).value=url;const label=el.closest('label');let img=label.querySelector('img');if(!img){img=document.createElement('img');img.alt='Uploaded preview';label.append(img)}img.src=url}else{draft.gallery[Number(el.dataset.galleryUpload)].image=url;renderGallery()}document.querySelector('#content-status').textContent='Photo uploaded. Save draft or publish when ready.'}catch(err){document.querySelector('#content-status').textContent=err.message}finally{el.disabled=false}};
section.onclick=e=>{const remove=e.target.closest('[data-gallery-remove]'),move=e.target.closest('[data-gallery-move]');if(e.target.id==='add-gallery'){collect();draft.gallery.push({image:'',caption:'',alt:''});renderGallery()}if(remove){collect();draft.gallery.splice(Number(remove.dataset.galleryRemove),1);renderGallery()}if(move){collect();const i=Number(move.dataset.galleryMove),j=i+Number(move.dataset.step);if(j>=0&&j<draft.gallery.length){[draft.gallery[i],draft.gallery[j]]=[draft.gallery[j],draft.gallery[i]];renderGallery()}}};
let contentStamps={};
// Only save if nobody changed this content since it was loaded here (prevents overwriting newer edits).
async function save(id){const value=validate();const guard=contentStamps[id]?'&updated_at=eq.'+encodeURIComponent(contentStamps[id]):'';const rows=await db('bloom_site_content?id=eq.'+id+guard,{method:'PATCH',body:JSON.stringify({data:value,updated_at:new Date().toISOString()})});if(!rows.length)throw Error(guard?'This content was changed somewhere else since you opened it (another admin, device or tab). Refresh this page to load the latest version, then make your change again.':'Content was not saved. Check your admin permissions.');contentStamps[id]=rows[0].updated_at;return value}
document.querySelector('#save-content').onclick=async e=>{e.target.disabled=true;try{await save('draft');document.querySelector('#content-status').textContent='Draft saved. The published website is unchanged.'}catch(err){document.querySelector('#content-status').textContent=err.message}finally{e.target.disabled=false}};
document.querySelector('#preview-content').onclick=()=>{try{localStorage.setItem('bloom-content-preview',JSON.stringify(validate()));window.open('/?preview=1','_blank','noopener')}catch(err){document.querySelector('#content-status').textContent=err.message}};
document.querySelector('#publish-content').onclick=async e=>{e.target.disabled=true;try{const value=validate();await save('draft');await save('published');published=structuredClone(value);document.querySelector('#content-status').textContent='Published. Refresh the website to see your changes.'}catch(err){document.querySelector('#content-status').textContent=err.message}finally{e.target.disabled=false}};
document.querySelector('#restore-content').onclick=()=>{draft=C.merge(published);render();document.querySelector('#content-status').textContent='Loaded published content into the editor. Save draft to keep it.'};
async function loadContent(){try{const rows=await db('bloom_site_content?select=id,data,updated_at');contentStamps={};rows.forEach(r=>contentStamps[r.id]=r.updated_at);published=C.merge(rows.find(r=>r.id==='published')?.data||{});draft=C.merge(rows.find(r=>r.id==='draft')?.data||{});render()}catch(err){document.querySelector('#content-status').textContent=err.message}}
const oldLoad=load;load=async()=>{await oldLoad();await loadContent()};if(session)loadContent();
document.head.insertAdjacentHTML('beforeend','<style>.video-edit{margin-top:12px;padding-top:12px;border-top:1px dashed #e4d4dc}.video-prev{display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap}.video-prev video{width:150px;aspect-ratio:3/2;object-fit:cover;border-radius:8px;background:#f5e8e5}</style>');
const oldRender=renderServices;renderServices=function(){oldRender();document.querySelectorAll('.service-form').forEach(form=>{const service=services[Number(form.dataset.index)],area=document.createElement('div');area.innerHTML=`<label>Photo URL<input name="image_url" value="${esc(service.image_url||'')}"></label><label>Photo description<input name="image_alt" value="${esc(service.image_alt||service.name)}"></label><label>Upload treatment photo<input type="file" accept="image/jpeg,image/png,image/webp,image/avif"></label><input type="hidden" name="image_position" value="${esc(service.image_position||'50% 50%')}"><div class="video-edit"><label>Treatment video (optional, plays on the card instead of the photo)<input name="video_url" value="${esc(service.video_url||'')}" placeholder="Upload below or paste a video link"></label><label>Upload treatment video (MP4/MOV, up to 50 MB)<input type="file" data-video-upload accept="video/mp4,video/quicktime,video/webm"></label><div class="video-prev"></div></div>`;form.querySelector('button').parentElement.before(area);const head=document.createElement('div');head.className='two';head.innerHTML=`<label>Treatment name<input name="name" required minlength="2" maxlength="120" value="${esc(service.name)}"></label><label>Category<select name="category">${[...new Set(['Full sets','Refills','Lift & tint',service.category])].map(c=>`<option ${c===service.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`;form.querySelector('h3').after(head);form.querySelector('h3+div+p')?.remove();const del=document.createElement('button');del.type='button';del.className='secondary danger';del.dataset.deleteService=form.dataset.index;del.textContent='Delete treatment';form.querySelector('button').after(' ',del);if(window.bloomFocus){const hid=area.querySelector('[name=image_position]'),urlIn=area.querySelector('[name=image_url]'),pick=window.bloomFocus.picker({src:C.safeImage(service.image_url)?service.image_url:'',value:hid.value,shape:'card',onChange:v=>hid.value=v});area.append(pick);const sync=()=>pick.setSrc(C.safeImage(urlIn.value)?urlIn.value:'');urlIn.addEventListener('input',sync);new MutationObserver(sync).observe(urlIn,{attributes:true,attributeFilter:['value']});area._sync=sync}const vIn=area.querySelector('[name=video_url]'),vBox=area.querySelector('.video-prev'),drawV=()=>{vBox.replaceChildren();if(!okVideo(vIn.value.trim()))return;const v=document.createElement('video');v.src=vIn.value.trim();v.muted=true;v.loop=true;v.autoplay=true;v.playsInline=true;v.setAttribute('playsinline','');v.controls=true;const rm=document.createElement('button');rm.type='button';rm.className='secondary danger';rm.textContent='Remove video';rm.onclick=()=>{vIn.value='';drawV();document.querySelector('#dashboard-status').textContent='Video removed. Save the treatment to update the website.'};vBox.append(v,rm)};vIn.addEventListener('change',drawV);drawV();
area.querySelector('[data-video-upload]').onchange=async e=>{const file=e.target.files[0];if(!file)return;const st=document.querySelector('#dashboard-status');e.target.disabled=true;st.textContent='Uploading video… keep this page open.';try{vIn.value=await uploadVideo(file);drawV();st.textContent='Video uploaded. Tap Save treatment to show it on the website.'}catch(err){st.textContent=err.message}finally{e.target.disabled=false;e.target.value=''}};
area.querySelector('[type=file]:not([data-video-upload])').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;e.target.disabled=true;area.querySelector('[name=image_url]').value=await upload(file);area._sync?.();document.querySelector('#dashboard-status').textContent='Photo uploaded. Save the treatment to show it on the website.'}catch(err){document.querySelector('#dashboard-status').textContent=err.message}finally{e.target.disabled=false}}})};
document.querySelector('#services').onsubmit=async e=>{e.preventDefault();const form=e.target,s=services[Number(form.dataset.index)],f=new FormData(form),button=e.submitter;button.disabled=true;try{const image=f.get('image_url').trim();if(image&&!C.safeImage(image))throw Error('Use an uploaded image or HTTPS image URL.');const newName=String(f.get('name')||'').trim(),newCat=f.get('category');if(newName!==s.name||newCat!==s.category){await bloomRpc('bloom_admin_update_service',{p_old:s.name,p_name:newName,p_category:newCat});s.name=newName;s.category=newCat;form.querySelector('h3').textContent=newName}const rows=await db('bloom_services?name=eq.'+encodeURIComponent(s.name),{method:'PATCH',body:JSON.stringify({price_zmw:Number(f.get('price')),duration_minutes:Number(f.get('duration')),description:f.get('description').trim(),active:f.get('active')==='on',image_url:image||null,image_alt:f.get('image_alt').trim(),image_position:window.bloomFocus?.valid(f.get('image_position'))?f.get('image_position'):null,video_url:(()=>{const v=String(f.get('video_url')||'').trim();if(v&&!okVideo(v))throw Error('Video links must start with https://');return v||null})()})});if(!rows.length)throw Error('Treatment was not updated.');services[Number(form.dataset.index)]=rows[0];document.querySelector('#dashboard-status').textContent='Treatment saved and live on the website.'}catch(err){document.querySelector('#dashboard-status').textContent=err.message}finally{button.disabled=false}};
document.querySelector('#services').addEventListener('click',async e=>{const b=e.target.closest('[data-delete-service]');if(!b)return;const s=services[Number(b.dataset.deleteService)];if(b.dataset.confirm!=='1'){b.dataset.confirm='1';b.textContent='Tap again to delete “'+s.name+'”';return}b.disabled=true;try{const how=await bloomRpc('bloom_admin_delete_service',{p_name:s.name});await load();document.querySelector('#dashboard-status').textContent=how==='archived'?'“'+s.name+'” is deleted from the website and this list. Past bookings for it are kept.':'“'+s.name+'” is deleted.'}catch(err){document.querySelector('#dashboard-status').textContent=err.message;b.disabled=false}});
const add=document.createElement('details');add.className='card';add.innerHTML='<summary>Add a treatment</summary><form id="add-treatment"><label>Name<input name="name" required maxlength="120"></label><label>Category<select name="category"><option>Full sets</option><option>Refills</option><option>Lift &amp; tint</option></select></label><label>Price (ZMW)<input name="price" type="number" min="0.01" step="0.01" required></label><label>Duration (minutes)<input name="duration" type="number" min="15" max="480" step="1" required></label><label>Description<textarea name="description" required maxlength="1000"></textarea></label><button>Add treatment</button></form>';document.querySelector('#services').before(add);
document.querySelector('#add-treatment').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);e.submitter.disabled=true;try{await db('bloom_services',{method:'POST',body:JSON.stringify({name:f.get('name').trim(),category:f.get('category'),price_zmw:Number(f.get('price')),duration_minutes:Number(f.get('duration')),description:f.get('description').trim(),active:true,sort_order:services.length+1})});e.target.reset();await load();document.querySelector('#dashboard-status').textContent='Treatment added. Upload a photo in its edit card.'}catch(err){document.querySelector('#dashboard-status').textContent=err.message}finally{e.submitter.disabled=false}};
})();
